''',
  'equity': r'''
# yaml-language-server: $schema=../../schema/pack.schema.json
# Shapes from public samples, rewritten as synthetic fixtures. Equity
# charges for alerts and people can opt out, so some will have none.
schema: 1
id: equity
name: Equity Bank
