  'kcb': r'''
# yaml-language-server: $schema=../../schema/pack.schema.json
# The first rules' shapes are illustrative and must be checked against real
# alerts. The loan, Mobi and M-Pesa rules follow real KCB messages, rewritten
# as synthetic samples in fixtures.yaml.
schema: 1
id: kcb
name: KCB
version: 0.4.1
min_engine: 0.4.0
currency: KES
utc_offset: "+03:00"
senders:
  - KCB
time_format: "dd/MM/yyyy 'at' HH:mm"

# No rule reads declined card payments ("... has been declined. Reason -
# Insufficient funds.Balance KES..."): no money moved, so their balance is
# never taken as the account's. The declined_card_payment notice below drops
# them instead of leaving them in the review inbox.
rules:
  # A loan repaid from the KCB account. "account" is the loan's number,
  # "counterparty" the loan as printed, "owed" the balance left and "due"
  # when the next instalment is due. No time is printed.
  - id: loan_repayment
    type: loan_repayment
    direction: out
    due_format: dd/MM/yyyy
    pattern: '^Dear [^,]+, (?<currency>[A-Z]{3}) ?(?<amount>[\d,]+\.\d{2}) was debited from your KCB account to repay your (?<counterparty>KCB .+?) (?<account>\d+)\. The loan has been partially paid\. Your loan balance is [A-Z]{3} ?(?<owed>[\d,]+\.\d{2}), next instalment is due on (?<due>\d{2}/\d{2}/\d{4})\.'

  # A debit or credit on the account through a channel KCB names ("Mobi",
  # "Pesalink Outgoing", "Direct Credits", ...), kept as "counterparty" since
  # the message names no other party. The account number is printed in full.
  # It can be the twin of a richer message about the same money (a PesaLink
  # completion, say): the app keeps one transaction for both.
  - id: account_movement
    type: bank
    direction_values:
      debited: out
      credited: in
    time_format: "HH:mm:ss 'on' dd MMM yyyy"
    pattern: '^Dear Customer, your acc (?<own_account>[\d*]+) has been (?<direction>credited|debited) (?<currency>[A-Z]{3}) ?(?<amount>[\d,]+\.\d{2}) (?<counterparty>.+?) at .+? at (?<time>\d{2}:\d{2}:\d{2} on \d{2} [A-Za-z]{3} \d{4})\.'

  # KCB's confirmation of an M-Pesa payment to its paybill. The money left
  # the M-Pesa wallet, so the rule names M-Pesa's account; KCB's own credit
  # alert records the other side. "account" is the KCB account paid into, as
  # printed (masked), and "receipt" the M-Pesa reference, which M-Pesa's own
  # message for the same payment also prints.
  - id: mpesa_paybill
    type: paybill
    direction: out
    institution: mpesa
    time_format: "dd/MM/yyyy 'at' hh:mm a"
    pattern: '^Ksh ?(?<amount>[\d,]+\.\d{2}) sent to (?<counterparty>KCB) Pay Bill \d+ for account (?<account>[\d*]+) .+? has been received on (?<time>\d{2}/\d{2}/\d{4} at \d{2}:\d{2} [AP]M)\. M-PESA ref (?<receipt>[A-Z0-9]{10})\.'

  # Money from someone's KCB account into this M-Pesa wallet: the mirror of
  # wallet_transfer. It lands on M-Pesa, not on a KCB account. "account" is
  # the sender's masked KCB account, "counterparty" their name.
  - id: mpesa_received
    type: received
    direction: in
    institution: mpesa
    time_format: "yyyy-MM-dd hh:mm:ss a"
    pattern: '^(?<receipt>[A-Z0-9]{16}) Confirmed\.\s+(?<currency>[A-Z]{3}) ?(?<amount>[\d,]+\.\d{2}) received from (?<counterparty>.+?) - (?<account>[\d*]+) on (?<time>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} [AP]M) via KCB\.'

  # Sent over PesaLink to an account at another bank, often the person's
  # own. "account" is the receiving account as printed, "counterparty" its
  # holder, and "fee" the transaction cost, which already includes the tax
  # printed after it. The receipt is KCB's long reference.
  - id: pesalink_sent
    type: bank
    direction: out
    time_format: "yyyy-MM-dd hh:mm:ss a"
    pattern: '^(?<receipt>[A-Za-z0-9]{20,40}) Completed\. Your SEND TO PESALINK request of (?<currency>[A-Z]{3}) ?(?<amount>[\d,]+\.\d{2}) from (?<own_account>[\d*]+) to (?<account>[\d*]+) - (?<counterparty>.+?) at (?<time>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} [AP]M) has been processed successfully\. Transaction cost [A-Z]{3} ?(?<fee>[\d,]+\.\d{2})'

  # A card payment that went through. The merchant is whatever follows
  # "at" (a name, a domain or a phone number). The time is 24-hour with a
  # stray "pm". The available balance is not read: it is in the account's
  # currency, while the amount is often in another (USD), and a message
  # carries one currency. The card number is not read as the account
  # either, so the payment lands on the KCB account, not a separate card.
  # A declined payment starts the same way but has no ", Avail balance";
  # the declined_card_payment notice drops it.
  - id: card_payment
    type: bank
    direction: out
    time_format: "dd/MM/yyyy HH:mm"
    pattern: '^(?<currency>[A-Z]{3}) ?(?<amount>[\d,]+\.\d{2}) transaction made on KCB card [\d*]+ at (?<counterparty>.+?) on (?<time>\d{2}/\d{2}/\d{4} \d{2}:\d{2})(?:[AaPp][Mm])?, Avail balance '

  - id: account_alert
    type: bank
    direction_values:
      debited: out
      credited: in
    pattern: '^Dear Customer, (?<currency>[A-Z]{3}) ?(?<amount>[\d,]+\.\d{2}) has been (?<direction>debited|credited) (?:from|to) your account (?<own_account>[\d*]+) on (?<time>\d{2}/\d{2}/\d{4} at \d{2}:\d{2})\. Transaction Ref: (?<receipt>[A-Z0-9]+)\. Your available balance is [A-Z]{3} ?(?<balance>[\d,]+\.\d{2})\.'

  # Sent from a KCB account to a mobile wallet; the receipt leads.
  # "account" is the masked KCB account, "counterparty" the recipient.
  - id: wallet_transfer
    type: bank
    direction: out
    time_format: "yyyy-MM-dd hh:mm:ss a"
    pattern: '^(?<receipt>[A-Z0-9]{16})\s+(?<currency>[A-Z]{3}) ?(?<amount>[\d,]+\.\d{2}) sent from (?<own_account>[\d*]+) to \S+ - (?<counterparty>.+?) on (?<time>\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} [AP]M)\.'

  - id: account_named
    type: bank
    direction_values:
      debited: out
      credited: in
    time_format: "dd/MM/yyyy 'at' h:mm a"
    pattern: '^Dear [^,]+, your KCB A/C (?<own_account>[\d*]+) has been (?<direction>debited|credited) with (?<currency>[A-Z]{3}) ?(?<amount>[\d,]+\.\d{2}) (?:from|to) (?<counterparty>.+?) on (?<time>\d{2}/\d{2}/\d{4} at \d{1,2}:\d{2} [AP]M)\. Ref: (?<receipt>[A-Z0-9]+)\. Avail Bal [A-Z]{3} ?(?<balance>[\d,]+\.\d{2})'

# Messages known not to be transactions, tried only when no rule matched.
# The app drops them without asking the person.
notices:
  # A card payment KCB refused ("... has been declined. Reason - ..."). No
  # money moved, and its "Balance" is not read.
  - id: declined_card_payment
    pattern: '^[A-Z]{3} ?[\d,]+\.\d{2} transaction made on KCB card [\d*]+ at .+? on \d{2}/\d{2}/\d{4} \d{2}:\d{2}(?:[AaPp][Mm])? has been declined\.'
''',
