  - id: till
    type: till
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) [Cc]onfirmed\. Ksh(?<amount>[\d,]+\.\d{2}) paid to (?<counterparty>.+?)\.? on (?<time>\d{1,2}/\d{1,2}/\d{2} at \d{1,2}:\d{2} [AP]M)\.?\s*New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.\s*Transaction cost, Ksh(?<fee>[\d,]+\.\d{2})\.'

  - id: withdrawal
    type: withdrawal
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) [Cc]onfirmed\.\s*on (?<time>\d{1,2}/\d{1,2}/\d{2} at \d{1,2}:\d{2} [AP]M)\s*Withdraw Ksh(?<amount>[\d,]+\.\d{2}) from (?<account>\d+) - (?<counterparty>.+?) New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.\s*Transaction cost, Ksh(?<fee>[\d,]+\.\d{2})\.'

  - id: airtime
    type: airtime
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) [Cc]onfirmed\.\s*You bought Ksh(?<amount>[\d,]+\.\d{2}) of airtime on (?<time>\d{1,2}/\d{1,2}/\d{2} at \d{1,2}:\d{2} [AP]M)\.\s*New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.\s*Transaction cost, Ksh(?<fee>[\d,]+\.\d{2})\.'

  # Fuliza notices print no transaction time; the engine uses the time the
  # phone received the message.
  - id: fuliza
    type: fuliza
    direction: in
    # The total still owed includes daily charges added since the last
    # message, so the app can tell them apart from draws and access fees.
    due_format: d/M/yy
    pattern: '^(?<receipt>[A-Z0-9]{10}) Confirmed\. Fuliza M-(?:PESA|Pesa) amount is Ksh ?(?<amount>[\d,]+\.\d{2})\. Access Fee charged Ksh ?(?<fee>[\d,]+\.\d{2})\.(?: Total Fuliza M-(?:PESA|Pesa) outstanding amount is Ksh ?(?<owed>[\d,]+\.\d{2}) due on (?<due>\d{1,2}/\d{1,2}/\d{2})\.?)?'

  - id: fuliza_repayment
    type: fuliza_repayment
    direction: out
    # Wording varies: "M-Pesa" in mixed case, and "outstanding Fuliza
    # M-PESA amount" on partial repayments.
    ignore_case: true
    pattern: '^(?<receipt>[A-Z0-9]{10}) Confirmed\. Ksh ?(?<amount>[\d,]+\.\d{2}) from your M-PESA has been used to (?:fully|partially) pay your outstanding Fuliza M-PESA(?: amount)?\..*?M-PESA balance is Ksh ?(?<balance>[\d,]+\.\d{2})\.'

  # "account" holds the receipt of the transaction being reversed. Money
  # comes back to the sender ("credited") or is taken back from the
  # recipient ("debited").
  - id: reversal
    type: reversal
    direction_values:
      credited: in
      debited: out
    pattern: '^(?<receipt>[A-Z0-9]{10})\s+[Cc]onfirmed\. Reversal of transaction (?<account>[A-Z0-9]{10}) has been successfully reversed\s+on (?<time>\d{1,2}/\d{1,2}/\d{2}\s+at \d{1,2}:\d{2} [AP]M)\s+and Ksh(?<amount>[\d,]+\.\d{2}) is (?<direction>credited|debited) (?:to|from) your M-PESA account\.\s*New M-PESA (?:account )?balance is Ksh(?<balance>[\d,]+\.\d{2})\.'

  # M-Shwari savings, typed as the statement pack types them.
  - id: mshwari_deposit
    type: paybill
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) [Cc]onfirmed\.\s*Ksh(?<amount>[\d,]+\.\d{2}) transferred to (?<counterparty>M-Shwari) account on (?<time>\d{1,2}/\d{1,2}/\d{2}\s+at \d{1,2}:\d{2} [AP]M)\.\s*M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\s*\.\s*New M-Shwari saving account balance is Ksh[\d,]+\.\d{2}\.\s*Transaction cost Ksh\.?\s*(?<fee>[\d,]+\.\d{2})'

  - id: mshwari_withdraw
    type: received
    direction: in
    pattern: '^(?<receipt>[A-Z0-9]{10}) [Cc]onfirmed\.\s*Ksh(?<amount>[\d,]+\.\d{2}) transferred from (?<counterparty>M-Shwari) account on (?<time>\d{1,2}/\d{1,2}/\d{2}\s+at \d{1,2}:\d{2} [AP]M)\.\s*M-Shwari balance is Ksh[\d,]+\.\d{2}\s*\.\s*M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\s*\.\s*Transaction cost Ksh\.?\s*(?<fee>[\d,]+\.\d{2})'

  # Airtime for another number; "account" holds that number.
  - id: airtime_other
    type: airtime
    direction: out
    pattern: '^(?<receipt>[A-Z0-9]{10}) [Cc]onfirmed\.\s*Ksh(?<amount>[\d,]+\.\d{2}) of airtime for (?<account>\d{9,12}) on (?<time>\d{1,2}/\d{1,2}/\d{2}\s+at \d{1,2}:\d{2} [AP]M)\.?\s*New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.'

  # Cash deposited at an agent.
  - id: deposit
    type: received
    direction: in
    pattern: '^(?<receipt>[A-Z0-9]{10}) [Cc]onfirmed\.\s*On (?<time>\d{1,2}/\d{1,2}/\d{2}\s+at \d{1,2}:\d{2} [AP]M)\s*Give Ksh(?<amount>[\d,]+\.\d{2}) cash to (?<counterparty>.+?)\s+New M-PESA balance is Ksh(?<balance>[\d,]+\.\d{2})\.'
''',
  'standard_chartered': r'''
# yaml-language-server: $schema=../../schema/pack.schema.json
# Standard Chartered Kenya account and card alerts, from sender StanChart
# (confirmed). Shapes come from real alerts, rewritten as synthetic samples.
schema: 1
id: standard_chartered
name: Standard Chartered
version: 0.2.0
min_engine: 0.2.0
currency: KES
utc_offset: "+03:00"
senders:
  - StanChart

rules:
  # "Dear Client, KES 100000.00 has been deposited to Acc. ending with 1234."
  # No time, reference or balance: the time is when the phone got it.
  - id: deposit
    type: bank
    direction: in
    pattern: '^Dear Client, (?<currency>[A-Z]{3}) ?(?<amount>[\d,]+(?:\.\d{1,2})?) has been deposited to Acc\. ending with (?<own_account>\d{3,6})\.'

  # "Dear Client, a transaction of KES 1900.00 was made on card ending 1234
  # at SHOP NAME 1234567 on 2026-11-08." The trailing number is the shop's
  # terminal, not part of its name. The message gives a date but no time,
  # so the time is when the phone got it.
  - id: card_payment
    type: bank
    direction: out
    pattern: '^Dear Client, a transaction of (?<currency>[A-Z]{3}) ?(?<amount>[\d,]+(?:\.\d{1,2})?) was made on card ending (?<own_account>\d{3,6}) at (?<counterparty>.+?)(?: \d{4,})? on \d{4}-\d{2}-\d{2}\.'
''',
};

/// The YAML source of every statement pack in `packs/*/statement.yaml`, by id.
const bundledStatementPackSources = <String, String>{
  'mpesa_statement': r'''
# yaml-language-server: $schema=../../schema/statement-pack.schema.json
# The Safaricom M-Pesa full statement (PDF). Column names and detail wording
# follow the public statement layout; fixtures are synthetic.
schema: 1
id: mpesa_statement
institution: mpesa
name: M-Pesa statement
version: 0.2.0
currency: KES
utc_offset: "+03:00"

detect:
  - '^\s*M-?PESA\s+STATEMENT\b'
  - 'Receipt No\.?\s+Completion Time\s+Details'

period: 'Statement Period:?\s+(?<start>\d{1,2} [A-Za-z]{3} \d{4})\s+-\s+(?<end>\d{1,2} [A-Za-z]{3} \d{4})'
period_format: "d MMM yyyy"

columns:
  - key: reference
    header: '^Receipt No\.?$'
    pattern: '^[A-Z0-9]{10}$'
  - key: date
    header: '^Completion Time$'
    format: "yyyy-MM-dd HH:mm:ss"
  - key: description
    header: '^Details$'
  - key: status
    header: '^Transaction Status$'
  - key: money_in
    header: '^Paid In$'
    align: right
  # Withdrawals are printed with a minus sign.
  - key: money_out
    header: '^Withdrawn$'
    align: right
    negative: true
  - key: balance
    header: '^Balance$'
    align: right

row_starts_with: reference
order: detect
completed_status: '^Completed$'
skip:
  - '^Page \d+ of \d+'
  - '^Disclaimer\b'

# A payment's charge is a separate row with the same receipt.
fees:
  description: '^[A-Za-z ]+ Charge$'

# First match wins. Detail wording follows the real statement; counterparty
# names come after the masked phone number, with no dash between them.
rules:
  - id: paybill
    type: paybill
    pattern: '^Pay Bill(?: Online)?(?: Fuliza M-?Pesa)?(?: Online)? to \d+ - (?<counterparty>.+?) Acc\.? ?(?<account>\S.*)$'
  - id: till
    type: till
    pattern: '^Merchant Payment(?: Fuliza M-?Pesa)?(?: Online)? to (?<account>\d+) - (?<counterparty>.+)$'
  # Pochi la Biashara: paying a small business on its phone number.
  - id: small_business
    type: till
    pattern: '^Customer (?:Payment to Small Business|Send Money to Micro SME Business(?: with Fuliza M-?Pesa)?) to - (?<account>\S+) (?<counterparty>.+)$'
  - id: sent
    type: sent
    pattern: '^Customer Transfer(?: Fuliza M-?Pesa)? to - (?<account>\S+) (?<counterparty>.+)$'
  - id: received
    type: received
    pattern: '^Funds received from - (?<account>\S+) (?<counterparty>.+)$'
  - id: business_payment
    type: received
    pattern: '^(?:Business|Promotion) Payment from (?<account>\d+) - (?<counterparty>.+?)(?: via API.*)?$'
  # Money moved in from a bank account.
  - id: from_bank
    type: received
    pattern: '^Transfer from Bank (?<account>\d+) - (?<counterparty>.+?) to Customer via API$'
  # Money market fund through M-Pesa: putting money in, and taking it out.
  - id: unit_trust_in
    type: paybill
    pattern: '^Unit Trust Invest To (?<account>\d+) - (?<counterparty>.+?)(?: by .+)?$'
  - id: unit_trust_out
    type: received
    pattern: '^Unit Trust \S+ From (?<account>\d+) - (?<counterparty>.+?)(?: by .+)?$'
  # M-Shwari savings: deposits leave M-Pesa, withdrawals come back.
  - id: mshwari_deposit
    type: paybill
    pattern: '^M-Shwari Deposit\b'
  - id: mshwari_withdraw
    type: received
    pattern: '^M-Shwari Withdraw\b'
  # Mobile to bank, as "<Bank> M2B Transfer to <paybill> - <bank> for ...".
  - id: to_bank
    type: paybill
    pattern: '^\S+ [A-Z]\d[A-Z] Transfer to (?<account>\d+) - (?<counterparty>.+?)(?: for .*)?$'
  - id: withdrawal
    type: withdrawal
    pattern: '^Customer Withdrawal At Agent Till (?<account>\d+) - (?<counterparty>.+)$'
  - id: airtime
    type: airtime
    pattern: '^(?:Airtime Purchase|Recharge for Customer|Buy Bundles?|Customer Bundle Purchase)\b'
  - id: fuliza
    type: fuliza
    pattern: '^OverDraft of Credit Party\b'
  - id: fuliza_repayment
    type: fuliza_repayment
    pattern: '^OD Loan Repayment\b'
  - id: reversal
    type: reversal
    pattern: '\bReversal\b(?:.* of (?<account>[A-Z0-9]{10})\b)?'

password_hint: mpesa_statement
''',
};
